const canvas=$('#world'),ctx=canvas.getContext('2d');let H=560,offset=0;
function resize(){H=Math.round(840*$('#scene').clientHeight/$('#scene').clientWidth);canvas.width=840;canvas.height=H;offset=(H-560)/2;renderSpots()}
function renderSpots(){$('#hotspots').innerHTML=rooms[room].spots.map(([id,t,x,y])=>`<button class="spot ${['out','office','shop','map'].includes(id)?'exit':''} ${state.docs.includes(id)?'read':''}" data-spot="${id}" style="left:clamp(65px,${x/840*100}%,calc(100% - 65px));top:${(y+offset)/H*100}%">${t}</button>`).join('');document.querySelectorAll('[data-spot]').forEach(b=>b.onclick=()=>{let s=rooms[room].spots.find(s=>s[0]===b.dataset.spot);route=[{x:player.x,y:450},{x:s[4],y:450},{x:s[4],y:s[5]}];onArrival=()=>interact(s[0]);toast('Иду: '+s[1])})}
canvas.addEventListener('pointerdown',e=>{if(modal)return;let r=canvas.getBoundingClientRect();let x=(e.clientX-r.left)/r.width*840,y=(e.clientY-r.top)/r.height*H-offset;x=Math.max(55,Math.min(785,x));y=Math.max(room==='street'?370:390,Math.min(510,y));route=[{x,y}];onArrival=null});
const keys=new Set();window.addEventListener('keydown',e=>{if(e.key==='Escape'){if(modal)close();return}if(modal){if(e.key==='Tab'){const f=[...$('#panel').querySelectorAll('button,input')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}return}if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key)){e.preventDefault();keys.add(e.key);route=[];onArrival=null}});window.addEventListener('keyup',e=>keys.delete(e.key));window.addEventListener('blur',()=>keys.clear());
$('#notes').onclick=notebook;$('#help').onclick=help;$('#journal').onclick=assignment;$('#home').onclick=e=>{e.preventDefault();welcome()};$('#sound').onclick=()=>{sound=!sound;if(sound&&!audioContext)audioContext=new(window.AudioContext||window.webkitAudioContext)();$('#sound').textContent=sound?'♫ вкл.':'♫ выкл.';$('#sound').setAttribute('aria-label',sound?'Выключить звук шагов':'Включить звук шагов')};
function stepSound(){if(!sound||!audioContext||performance.now()-lastStep<210)return;lastStep=performance.now();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='triangle';o.frequency.setValueAtTime(95,audioContext.currentTime);g.gain.setValueAtTime(.025,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+.05);o.connect(g).connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+.06)}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h)}function line(x,y,a,b,c,w=1){ctx.strokeStyle=c;ctx.lineWidth=w;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(a,b);ctx.stroke()}function ellipse(x,y,rx,ry,c){ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fill()}function poly(points,c){ctx.fillStyle=c;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fill()}
function person(c,x,y,color,walk,phase){c.save();c.translate(Math.round(x),Math.round(y));c.fillStyle='#192e3435';c.beginPath();c.ellipse(0,4,19,7,0,0,7);c.fill();let s=walk?Math.sin(phase)*4:0;c.fillStyle='#343b34';c.fillRect(-11,-15+s,9,19);c.fillRect(3,-15-s,9,19);c.fillStyle='#202e29';c.fillRect(-13,1+s,12,5);c.fillRect(3,1-s,13,5);c.fillStyle=color;c.fillRect(-16,-44,32,34);c.fillRect(-22,-40-s,7,24);c.fillRect(15,-40+s,7,24);c.fillStyle='#ceb48b';c.fillRect(-22,-17-s,7,7);c.fillRect(15,-17+s,7,7);c.fillRect(-10,-64,21,23);c.fillStyle='#dfc69e';c.fillRect(-5,-61,17,16);c.fillStyle='#55453c';c.fillRect(-12,-67,24,8);c.fillRect(-13,-62,6,16);c.fillStyle='#ded8bd';c.fillRect(-5,-43,10,6);c.fillStyle='#3c4238';c.fillRect(6,-55,3,3);c.fillStyle='#bfa376';c.fillRect(-3,-27,3,3);c.fillRect(-3,-18,3,3);c.restore()}
function windowArt(x,y){rect(x-9,y-8,132,158,'#5b6652');rect(x,y,114,140,'#a9c6bd');rect(x+7,y+7,100,126,'#b7cfc0');poly([[x+7,y+55],[x+40,y+18],[x+65,y+55]],'#758a7a');rect(x+10,y+55,52,65,'#a1a88a');rect(x+51,y,7,140,'#e4dfc7');rect(x,y+64,114,7,'#e4dfc7');rect(x-15,y+140,144,12,'#b4ad8e');poly([[x+8,y+145],[x+105,y+145],[x+225,y+350],[x+85,y+350]],'#f3df9e17')}
function shelf(x,y,w){rect(x+6,y+6,w,175,'#3d3d3055');rect(x,y,w,175,'#685c43');for(let row=0;row<3;row++){rect(x+7,y+8+row*54,w-14,46,'#4a4937');for(let k=0;k<Math.floor((w-17)/15);k++){const col=['#8b6852','#7a8463','#b79b67','#5e7771','#ad795b'][(k+row*3)%5];rect(x+10+k*15,y+16+row*54,11,37-(k%3)*3,col);rect(x+12+k*15,y+23+row*54,7,2,'#d0b98b')}}rect(x-3,y+174,w+6,7,'#998364')}
function paper(x,y,w=35,h=28){rect(x+3,y+3,w,h,'#443e3130');rect(x,y,w,h,'#e9dec1');for(let i=0;i<4;i++)line(x+5,y+7+i*4,x+w-6-(i%2)*5,y+7+i*4,'#898574',1)}
function plant(x,y){rect(x-13,y,26,24,'#a77f5e');rect(x-16,y,32,6,'#be9770');for(let i=0;i<7;i++){let a=i*.9;line(x,y,x+Math.cos(a)*22,y-12-Math.sin(a)*30,'#536747',3);ellipse(x+Math.cos(a)*22,y-12-Math.sin(a)*30,9,5,'#6e8051')}}
function floor(){rect(0,-offset,840,H,'#b3a17a');for(let y=-offset;y<560+offset;y+=38){line(0,y,840,y,'#8f805b',2);for(let x=(Math.round(y/38)%2)*90;x<840;x+=180){line(x,y,x,y+38,'#8f805b');line(x+16,y+12,x+80,y+12,'#bba981');line(x+50,y+25,x+145,y+25,'#a99771')}}}
function officeArt(){floor();rect(0,-offset,840,230+offset,'#839078');rect(0,0,840,16,'#d1c5a0');for(let x=20;x<840;x+=72)line(x,-offset,x,230,'#7b8870');rect(0,220,840,13,'#56654d');rect(0,235,840,15,'#c1b28b');windowArt(570,46);shelf(80,48,180);rect(340,266,215,125,'#67513b');rect(330,252,235,115,'#ac8860');rect(338,259,220,97,'#bd9b6d');rect(344,365,12,38,'#594832');rect(536,365,13,38,'#594832');paper(367,274,60,40);paper(424,290,51,35);ellipse(502,285,10,7,'#35483d');line(504,279,521,252,'#eee5cb',3);rect(125,213,64,33,'#82624c');rect(129,210,60,7,'#e2d3b0');rect(127,205,60,7,'#79694b');plant(715,242);rect(287,33,105,102,'#675942');rect(295,41,89,86,'#b8aa86');ellipse(338,84,23,28,'#7c8168');rect(320,103,37,20,'#59674e');if(!state.intro||state.ending==='rescued')person(ctx,610,325,'#455c67',false,0);else{rect(594,300,32,35,'#726047');rect(594,288,32,8,'#846e50')}paper(66,414,44,25);rect(705,360,108,160,'#6f7057');rect(716,369,88,150,'#3d4a39');rect(720,372,75,142,'#766f50');rect(729,383,57,121,'#8c8059');ellipse(780,454,4,4,'#d7bd78');ellipse(95,435,32,17,'#6f7451');ellipse(95,426,31,13,'#8a8c63');rect(70,436,8,30,'#625b41');rect(112,436,8,30,'#625b41')}
function shopArt(){floor();rect(0,-offset,840,240+offset,'#87927b');rect(0,229,840,15,'#54634b');windowArt(65,38);shelf(240,35,230);shelf(505,35,235);rect(483,305,200,75,'#6b573e');rect(473,287,220,35,'#b7986b');for(let i=0;i<5;i++){rect(510+i*28,274-i%2*8,25,14,'#6f7b5b');rect(511+i*28,278-i%2*8,23,6,'#d5c8a6')}person(ctx,580,283,'#8b6d50',false,0);rect(130,225,145,110,'#8d7350');paper(147,237,104,64);rect(310,322,107,25,'#92764e');paper(325,307,69,37);rect(319,347,11,52,'#63513b');rect(399,347,11,52,'#63513b');rect(705,360,108,160,'#6f7057');rect(716,369,88,150,'#3d4a39');rect(720,372,75,142,'#766f50');rect(729,383,57,121,'#8c8059');ellipse(780,454,4,4,'#d7bd78');if(state.parcel==='none'||state.parcel==='left'){rect(629,266,45,25,'#c9b78a');line(651,266,651,291,'#6f6b4a',2);line(629,278,674,278,'#6f6b4a',2)}plant(55,352)}
function streetArt(){rect(0,-offset,840,H,'#87967a');for(let y=-offset;y<560+offset;y+=32)for(let x=0;x<840;x+=40){let v=Math.sin(x*19+y*7);if(v>.2)rect(x+12,y+8,3,7,'#74866a')}rect(55,320,735,260,'#b8af8f');for(let y=335;y<560+offset;y+=24)for(let x=60+(y%2)*15;x<790;x+=44){ellipse(x,y,17,7,(x+y)%3?'#c3b99b':'#a7a487');line(x-11,y+7,x+9,y+7,'#a1997e')}
function house(x,w,color){rect(x+8,48,w,275,'#3e584a33');rect(x,35,w,278,color);poly([[x-12,44],[x+w/2,-18],[x+w+12,44]],'#586453');rect(x+15,65,w-30,11,'#c6bea0');rect(x+20,94,65,92,'#5c7566');rect(x+25,99,55,82,'#a8c0aa');line(x+52,99,x+52,181,'#dbd5b6',5);line(x+25,140,x+80,140,'#dbd5b6',5);rect(x+w-95,192,66,120,'#4d5840');rect(x+w-89,198,54,114,'#7b7552');rect(x-6,310,w+12,17,'#8d8c6d');rect(x-12,328,w+24,12,'#a8a184')}
house(25,270,'#c1b790');house(540,275,'#b0b99a');rect(610,75,165,46,'#435b48');ctx.fillStyle='#e9d8b0';ctx.font='22px Georgia';ctx.textAlign='center';ctx.fillText('КНИГИ',692,105);rect(320,260,188,10,'#7f8260');rect(320,301,188,10,'#7f8260');for(let x=325;x<510;x+=25){rect(x,238,10,101,'#9a9971');poly([[x,238],[x+5,230],[x+10,238]],'#aaa780')}person(ctx,420,422,'#718159',false,0);paper(427,380,19,24);plant(520,322);ellipse(77,479,32,13,'#a5a990');ellipse(77,477,29,10,'#8b9a90');if(state.poet)paper(444,411,28,18)}
function draw(dt){ctx.clearRect(0,0,840,H);ctx.save();ctx.translate(0,offset);if(room==='office')officeArt();else if(room==='shop')shopArt();else if(room==='print')printArt();else if(room==='salon')salonArt();else if(room==='monastery')monasteryArt();else streetArt();let moving=false;if(!modal){let dx=(keys.has('ArrowRight')||keys.has('d')?1:0)-(keys.has('ArrowLeft')||keys.has('a')?1:0),dy=(keys.has('ArrowDown')||keys.has('s')?1:0)-(keys.has('ArrowUp')||keys.has('w')?1:0);if(dx||dy){let n=Math.hypot(dx,dy);player.x=Math.max(55,Math.min(785,player.x+dx/n*dt*.23));player.y=Math.max(room==='street'?370:390,Math.min(510,player.y+dy/n*dt*.23));moving=true}else if(route.length){let dest=route[0],dx=dest.x-player.x,dy=dest.y-player.y,d=Math.hypot(dx,dy),step=dt*.29;if(d<step+1){player.x=dest.x;player.y=dest.y;route.shift();if(!route.length&&onArrival){let fn=onArrival;onArrival=null;setTimeout(fn,0)}}else{player.x+=dx/d*step;player.y+=dy/d*step;moving=true}}}if(moving){tick+=dt*.018;stepSound()}if(route.length){let d=route.at(-1);ctx.strokeStyle='#f1e4b498';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(d.x,d.y,12,5,0,0,7);ctx.stroke()}person(ctx,player.x,player.y,'#b5704d',moving,tick);rect(player.x+10,player.y-35,12,22,'#6f583d');line(player.x-10,player.y-43,player.x+18,player.y-17,'#d0bb8d',3);ctx.fillStyle='#f5e6b9';ctx.beginPath();ctx.moveTo(player.x-5,player.y-82);ctx.lineTo(player.x+5,player.y-82);ctx.lineTo(player.x,player.y-76);ctx.fill();ctx.restore();}
let last=performance.now();function loop(now){draw(Math.min(now-last,1000));last=now;requestAnimationFrame(loop)}window.addEventListener('resize',resize);updateUI();resize();requestAnimationFrame(loop);welcome();
